# Maya import script (Blender -> Maya bridge). Generated by MayaBridge -- do not edit by hand.

"""Import the bridged payload (FBX or USD) into Maya, with optional clean-slate and
frame-on-import behaviors.

The single Maya-side recipe for the bridge. Two booleans pick the variant the artist wants
(this replaces what used to be three near-identical templates):

- ``CLEAR_SCENE`` -- open a new (empty) Maya scene first (clean-slate hand-off).
- ``FRAME_VIEW``  -- after import, select the new top-level objects and frame them (viewFit).

With both off this is a plain additive import into the current scene; both on clears then frames.

Post-import repairs (both best-effort -- a repair must never cost the user the import):

- **Empties -> correct Maya node types.** Blender Empties travel as FBX nulls and Maya's
  importer gives every null a locator shape, so a sent group hierarchy arrived as locators
  (live production report). An Empty WITH children is a Maya group (locator shape dropped); a
  childless Empty stays a locator (it marks a point); the manifest's ``empties`` section
  overrides the heuristic where the author marked intent (non-default display type, or the
  ``maya_node_type`` tag a round-tripped scene carries). Dependency-free copy, kept in step
  by hand with ``mayatk.BlenderSceneImport._restore_empty_groups`` (the pull direction's
  engine).
- **Native material rebuild.** Blender's FBX exporter only carries images wired (almost)
  directly into Principled sockets -- packed ORM/MSAO through SeparateColor, AO multiplies and
  node-group plumbing export as NOTHING, so real production materials arrived gray. MayaBridge
  now writes the same ``.manifest.json`` sidecar the pull direction uses (each material's
  ORIGINAL image files), and this script replays it through the ONE existing applier,
  ``mayatk.BlenderSceneImport._apply_texture_manifest`` (the established template->paired-engine
  contract; see both ``_bake_scene.py`` templates). Without mayatk on the target Maya the FBX's
  classic-model materials are kept, with a console line saying so.
"""

# Bridge metadata -- consumed by MayaBridge before substitution.
BRIDGE_MODES = ("send_to",)

# Export settings applied Blender-side before launch (read by MayaBridge; echoed here so the panel
# exposes them): scope=__SCOPE__ carrier=__CARRIER__ materials=__INCLUDE_MATERIALS__ embed_textures=__EMBED_TEXTURES__ apply_unit_scale=__APPLY_UNIT_SCALE__ include_animation=__INCLUDE_ANIMATION__ triangulate=__TRIANGULATE__
import os
import sys
import traceback

import maya.cmds as cmds
import maya.mel as mel

# The payload: FBX or USD, routed on the extension below. ``FBX_PATH`` is the
# historical name of the same path; the sidecar manifest hangs off it either way.
FBX_PATH = r"__PAYLOAD_PATH__"
USD_EXTENSIONS = (".usd", ".usda", ".usdc", ".usdz")
CARRIER = "usd" if FBX_PATH.lower().endswith(USD_EXTENSIONS) else "fbx"
# Roots for mayatk + pythontk, resolved in the parent Blender -- the child must not
# depend on its own environment to import the toolkit (mirror of mtk's template).
EXTRA_SYS_PATH = __EXTRA_SYS_PATH__
CLEAR_SCENE = __CLEAR_SCENE__
FRAME_VIEW = __FRAME_VIEW__
# Which Maya shader the manifest rebuild targets (GameShader's vocabulary:
# standard_surface / open_pbr / stingray).
SHADER_TYPE = __SHADER_TYPE__


# The *USD Import* translator options every hand-off importer uses -- mirror of
# mayatk ``UsdUtils.INTERCHANGE_IMPORT_OPTIONS`` (pinned equal): time samples as
# keys (the translator's default is OFF -- every animated prim arrived static,
# measured) and Blender's ``st`` (its exporter's name for the render-active UV
# map) landing as Maya's ``map1``, the FBX route's spelling.
USD_IMPORT_OPTIONS = "readAnimData=1;remapUVSetsTo=[[st,map1]]"


def import_fbx():
    """Import the payload deterministically; return the nodes it created.

    The FBX plugin's import options are global and sticky (the user's last
    interactive import shapes this one), and the factory "merge" mode can
    RETARGET animation onto same-named nodes already in the scene -- reset,
    then pin "add". Mirror of the pull engine's ``_import_fbx``; best-effort
    per command so a plugin build missing one can't block the import.

    ``FBXResetImport`` restores the factory take selector, which on Maya 2025
    is "No Animation" -- so the reset itself drops every animCurve unless the
    take is re-selected. Index ``-1`` is resolved per file at import time (last
    take, or none for a takeless file); a FIXED index aborts a takeless import
    and empties it. See mayatk ``FbxUtils.reset_import``.
    """
    for command in (
        "FBXResetImport",
        "FBXImportMode -v add",
        "FBXImportSetTake -ti -1",
    ):
        try:
            mel.eval(command)
        except Exception:
            print("FBX import option skipped (unsupported by this plugin): " + command)
    return (
        cmds.file(FBX_PATH, i=True, type="FBX", ignoreVersion=True, returnNewNodes=True)
        or []
    )


def import_usd():
    """Import a USD payload through mayaUsd's file translator; return the new nodes.

    The translator honors the active namespace like the FBX path and needs no
    sticky-option reset -- USD import options travel on the call.
    """
    if not cmds.pluginInfo("mayaUsdPlugin", query=True, loaded=True):
        cmds.loadPlugin("mayaUsdPlugin")
    return (
        cmds.file(
            FBX_PATH.replace("\\", "/"),
            i=True,
            type="USD Import",
            ignoreVersion=True,
            returnNewNodes=True,
            options=USD_IMPORT_OPTIONS,
        )
        or []
    )


def import_payload():
    """Run the importer the payload's extension names (FBX or USD)."""
    if CARRIER == "usd":
        return import_usd()
    if not cmds.pluginInfo("fbxmaya", query=True, loaded=True):
        cmds.loadPlugin("fbxmaya")
    return import_fbx()


def restore_usd_locators(new_nodes):
    """Give the Empties that mark a point their locator shape back (USD carrier).

    Off a USD layer every Blender Empty arrives as a SHAPELESS transform --
    groups are already right, point markers are invisible and unpickable. The
    engine path honors the manifest's ``empties`` section; the dependency-free
    fallback keeps the children heuristic (childless -> locator). Kept in step
    by hand with ``mayatk.BlenderSceneImport._restore_usd_locators``.
    """
    _extend_sys_path()
    try:
        from mayatk.env_utils.blender_bridge._scene_import import BlenderSceneImport

        BlenderSceneImport._restore_usd_locators(new_nodes, FBX_PATH + ".manifest.json")
        return
    except Exception as error:
        print("Locator repair via mayatk unavailable ({}); using the heuristic.".format(error))
    # exactType: a joint IS a transform, and a shapeless leaf joint is a
    # skeleton tip, not a point marker.
    for transform in cmds.ls(new_nodes, exactType="transform", long=True) or []:
        if cmds.listRelatives(transform, shapes=True, fullPath=True):
            continue
        if cmds.listRelatives(transform, children=True, type="transform", fullPath=True):
            continue
        short = transform.rsplit("|", 1)[-1].rsplit(":", 1)[-1]
        cmds.createNode("locator", name=short + "Shape", parent=transform)


def _fbx_safe_name(name):
    """*name* as Maya's FBX importer spells it (illegal chars -> ``FBXASC###``)."""
    out = []
    for i, ch in enumerate(name):
        legal = (
            "a" <= ch <= "z"
            or "A" <= ch <= "Z"
            or ch == "_"
            or (ch.isdigit() and i > 0)
        )
        out.append(ch if legal else "FBXASC%03d" % ord(ch))
    return "".join(out)


def _manifest_empty_rules():
    """``{fbx-spelled name: keep locator (None = heuristic)}`` from ``empties``.

    An explicit ``maya_node_type`` wins outright; a non-``PLAIN_AXES`` display
    type is a deliberate author marker and stays a locator even with children;
    ``PLAIN_AXES`` (Blender's default) maps to None -- the children heuristic.
    EVERY listed Empty gets an entry, unmarked ones included: the exact name
    pins the lookup, so the rename-on-clash digit-suffix match can never hand
    a real sibling ("grp2") another Empty's rule ("grp").
    """
    import json

    rules = {}
    manifest = FBX_PATH + ".manifest.json"
    if not os.path.isfile(manifest):
        return rules
    try:
        with open(manifest, "r") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return rules
    empties = data.get("empties") if isinstance(data, dict) else []
    for entry in empties or []:
        if not isinstance(entry, dict) or not entry.get("name"):
            continue
        name = _fbx_safe_name(entry["name"])
        node_type = str(entry.get("maya_node_type") or "").lower()
        if node_type:
            rules[name] = node_type == "locator"
        elif str(entry.get("display_type") or "PLAIN_AXES") != "PLAIN_AXES":
            rules[name] = True
        else:
            rules[name] = None
    return rules


def restore_empty_groups(new_nodes):
    """Restore imported Empties as the CORRECT Maya node types (see module docstring).

    Parent Empties become plain groups (locator shape dropped); childless ones
    stay locators; the manifest's ``empties`` section overrides the heuristic
    for Empties the author marked as locators (non-default display type or a
    round-tripped ``maya_node_type`` tag). Scoped to *new_nodes* so a
    pre-existing user locator is never touched; skips transforms with any
    non-locator shape. Kept in step by hand with
    ``mayatk.BlenderSceneImport._restore_empty_groups``.
    """
    rules = _manifest_empty_rules()
    for shape in cmds.ls(new_nodes, exactType="locator", long=True) or []:
        transform = (cmds.listRelatives(shape, parent=True, fullPath=True) or [None])[0]
        if not transform:
            continue
        shapes = cmds.listRelatives(transform, shapes=True, fullPath=True) or []
        if len(shapes) != 1:
            continue
        short = transform.rsplit("|", 1)[-1].rsplit(":", 1)[-1]
        keep = rules.get(short)
        if keep is None:  # tolerate Maya's rename-on-clash digit suffix
            keep = next(
                (
                    k
                    for want, k in rules.items()
                    if short.startswith(want) and short[len(want):].isdigit()
                ),
                None,
            )
        if keep is None:
            keep = not cmds.listRelatives(
                transform, children=True, type="transform", fullPath=True
            )
        if not keep:
            cmds.delete(shape)


def _extend_sys_path():
    """Make mayatk/pythontk importable here (mirror of mtk's import template)."""
    for entry in reversed(EXTRA_SYS_PATH or []):
        if entry and entry not in sys.path:
            sys.path.insert(0, entry)


def rebuild_materials(new_nodes):
    """Replay the sidecar manifest through mayatk's applier (see module docstring)."""
    manifest = FBX_PATH + ".manifest.json"
    if not os.path.isfile(manifest):
        return
    _extend_sys_path()
    try:
        from mayatk.env_utils.blender_bridge._scene_import import BlenderSceneImport
    except Exception as error:
        print(
            "mayatk unavailable ({}); keeping the FBX-carried materials.".format(error)
        )
        return
    try:
        BlenderSceneImport(log_level="WARNING")._apply_texture_manifest(
            manifest, new_nodes, shader_type=SHADER_TYPE, carrier=CARRIER
        )
    except Exception:
        print("Texture-manifest rebuild failed; keeping the carried materials:")
        traceback.print_exc()


def main():
    if CLEAR_SCENE:
        cmds.file(new=True, force=True)

    new_nodes = import_payload()
    # Each carrier gets the Empties wrong in its own way: FBX makes every null a
    # locator (strip the groups' shapes), USD makes every Empty shapeless (give
    # the point markers theirs back). Same manifest rules decide both.
    if CARRIER == "usd":
        restore_usd_locators(new_nodes)
    else:
        restore_empty_groups(new_nodes)
    rebuild_materials(new_nodes)

    if not FRAME_VIEW:
        return

    tops = [
        n
        for n in (cmds.ls(new_nodes, assemblies=True) or [])
        if cmds.objExists(n)
    ]
    if tops:
        cmds.select(tops, replace=True)
    try:
        cmds.viewFit()
    except Exception:
        pass


main()
